<template>
  <section class="library" :class="{ 'has-selection': !!selected || editing }" :aria-busy="busy">
    <header class="library-header">
      <div><h1>{{ heading }}</h1><p>{{ filter === 'recent' ? '最近七天保存或更新的内容' : '收集本地片段，在需要时找到它们。' }}</p></div>
      <div class="header-actions"><button type="button" :disabled="busy" @click="refresh">刷新</button><details ref="addMenu" class="add-menu"><summary>添加知识</summary><div>
        <button v-for="kind in ['note','article','code','link']" :key="kind" type="button" @click="createItem(kind)">{{ kind === 'link' ? '保存链接' : '新建' + KNOWLEDGE_TYPES[kind] }}</button>
        <hr /><button type="button" :disabled="busy" @click="collect(false)">添加文件</button><button type="button" :disabled="busy" @click="collect(true)">收集文件夹</button>
      </div></details></div>
    </header>
    <div class="library-toolbar"><input v-model="query" type="search" placeholder="搜索标题、正文和代码" aria-label="搜索知识" /><select v-model="kindFilter" aria-label="内容类型"><option value="">所有类型</option><option v-for="(label,key) in KNOWLEDGE_TYPES" :key="key" :value="key">{{ label }}</option></select></div>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
    <details v-if="batch && (batch.failures.length || batch.skipped.length)" class="batch-results"><summary>查看未保存和跳过的内容</summary><p v-for="failure in batch.failures" :key="failure.sourceId">{{ failure.sourceId }}：{{ failure.message }}</p><p v-for="entry in batch.skipped" :key="entry">{{ entry }}</p></details>
    <div class="library-content">
      <section class="item-list" aria-label="知识列表"><div class="list-heading"><span>{{ displayed.length }} 条内容</span><span v-if="loading || searching">正在查找…</span></div>
        <button v-for="item in displayed" :key="item.id" class="item-row" :class="{ selected: selected?.id === item.id }" type="button" @click="selectItem(item.id)">
          <span class="item-type">{{ KNOWLEDGE_TYPES[item.kind] || '资料' }}</span><strong>{{ item.title }}</strong><span v-if="item.favorite" class="star" aria-label="已收藏">★</span>
          <span class="item-excerpt">{{ excerpt(item) }}</span><span class="item-meta">{{ knowledgeStatus(item) }}</span><span v-if="item.topics.length" class="item-topics">{{ item.topics.join(' / ') }}</span>
        </button>
        <div v-if="!loading && !searching && !displayed.length" class="list-empty"><strong>{{ query ? '没有找到相关内容' : filter === 'all' ? '从一段值得留下的内容开始' : '这里还没有内容' }}</strong><p>{{ query ? '试试标题中的词或正文中的关键字。' : '可以写笔记、粘贴代码，或保存电脑中的文件。' }}</p><button v-if="filter === 'all' && !query" type="button" @click="createItem('note')">写一条笔记</button></div>
      </section>
      <section class="item-reader" aria-label="知识阅读与编辑">
        <form v-if="editing" class="item-editor" @submit.prevent="save">
          <header><button type="button" @click="closeEditor">取消</button><button type="submit" class="primary" :disabled="busy || (!draft.title.trim() && !draft.body.trim() && !draft.notes.trim())">{{ busy ? '正在保存…' : '保存知识' }}</button></header>
          <label>标题（可选）<input v-model="draft.title" maxlength="200" placeholder="留空会从内容生成标题" /></label>
          <label>类型<select v-model="draft.kind"><option v-for="(label,key) in KNOWLEDGE_TYPES" :key="key" :value="key">{{ label }}</option></select></label>
          <p v-if="draft.kind === 'link'" class="help">链接只保存地址和笔记，尚未抓取网页正文。</p>
          <label>{{ draft.kind === 'code' ? '代码' : draft.kind === 'link' ? '链接地址或正文' : '正文' }}<textarea v-model="draft.body" :class="{ 'code-input': draft.kind === 'code' }" rows="14" placeholder="粘贴或输入内容，无需绑定项目" /></label>
          <label>我的笔记<textarea v-model="draft.notes" rows="4" placeholder="补充解释、用途或自己的理解" /></label>
          <p class="help">保存后直接进入本地检索。原件和笔记分别保留，模型归类不会改写正文。</p>
        </form>
        <article v-else-if="selected && !reading" class="reader-article">
          <header class="reader-actions"><button class="back-list" type="button" @click="selected = null">返回列表</button><span>{{ KNOWLEDGE_TYPES[selected.kind] || '资料' }}</span><div><button type="button" :aria-pressed="selected.favorite" @click="favorite">{{ selected.favorite ? '已收藏' : '收藏' }}</button><button type="button" @click="editItem">编辑</button><details class="more-menu"><summary aria-label="更多操作">•••</summary><div><button type="button" @click="exportItem(false)">导出笔记</button><button v-if="selected.hasAsset" type="button" @click="exportItem(true)">导出原件</button><button type="button" @click="confirmDelete = true">删除条目</button></div></details></div></header>
          <h2>{{ selected.title }}</h2><p class="reader-state">{{ knowledgeStatus(selected) }}<span>更新于 {{ date(selected.updatedAt) }}</span></p>
          <div v-if="selected.parseStatus !== 'ready'" class="processing-info"><p>{{ selected.parseError || '原件已保存，尚未提取正文。' }}</p><button v-if="selected.hasAsset" type="button" :disabled="busy" @click="retry">重新提取</button><button v-if="selected.hasAsset" type="button" @click="exportItem(true)">导出原件</button></div>
          <pre v-if="selected.kind === 'code' && selected.body" class="code-body"><code>{{ selected.body }}</code></pre>
          <div v-else-if="selected.body" class="knowledge-prose" v-html="renderMarkdown(selected.body)" @click="onContentClick" />
          <p v-else class="help">暂无正文，可以通过“编辑”补充说明。</p>
          <section v-if="selected.notes" class="reader-notes"><h3>我的笔记</h3><div class="knowledge-prose" v-html="renderMarkdown(selected.notes)" @click="onContentClick" /></section>
          <section class="reader-topics"><h3>主题</h3><form @submit.prevent="setTopics"><input v-model="topicText" aria-label="主题，以逗号分隔" placeholder="添加主题，以逗号分隔" /><button type="submit" :disabled="busy">保存归属</button></form><p class="help">可属于多个主题。手动归属优先于模型。</p>
            <div v-if="selected.suggestedTopics.length" class="suggestions"><span>模型建议：</span><button v-for="topic in selected.suggestedTopics" :key="topic" type="button" @click="acceptTopic(topic)">＋ {{ topic }}</button><button type="button" @click="dismissSuggestions">忽略建议</button></div>
            <p v-if="selected.classificationError" class="help">自动归类未完成：{{ selected.classificationError }}</p>
            <button type="button" :disabled="classifying.has(selected.id) || !selected.modelAllowed || selected.manualTopics" @click="classify(selected.id)">{{ classifying.has(selected.id) ? '正在归类…' : selected.manualTopics ? '已固定手动归属' : '重新建议主题' }}</button>
          </section>
          <details class="reader-source"><summary>来源与版本</summary><p>{{ selected.sourceId }}</p><p>版本标识：{{ selected.versionId }}</p><p>{{ selected.hasAsset ? '原件副本保存在本机，原文件移动不会影响此副本。' : '正文与修改历史保存在本机。' }}</p></details>
        </article>
        <div v-else class="reader-empty"><p>{{ reading ? '正在读取内容…' : '选择一条知识，阅读原文与笔记' }}</p><span>对话中会按需查找相关内容，并提供出处。</span></div>
      </section>
    </div>
    <footer class="library-footer"><label><input type="checkbox" :checked="aiEnabled" :disabled="changingPolicy" @change="changePolicy" />允许当前模型整理并引用我的个人知识</label><span>开启后发送相关摘录用于归类和对话；关闭时仅在本机保存、检索和手动归类。</span></footer>
    <n-modal :show="confirmDelete" preset="dialog" title="删除这条知识？" content="将移除正文、版本和检索记录。原电脑中的文件不会被删除。" positive-text="删除" negative-text="取消" @positive-click="remove" @negative-click="confirmDelete = false" @close="confirmDelete = false" />
    <n-modal :show="leaveAction !== null" preset="dialog" title="放弃尚未保存的修改？" content="你的正文尚未保存，继续会丢失本次修改。" positive-text="放弃修改" negative-text="继续编辑" @positive-click="confirmLeave" @negative-click="leaveAction = null" @close="leaveAction = null" />
  </section>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { NModal } from 'naive-ui';
import * as ipc from '../lib/ipc';
import type { KnowledgeItem, KnowledgeItemInput, KnowledgeCollectResult } from '../lib/types';
import { filterKnowledgeItems, KNOWLEDGE_TYPES, knowledgeStatus, parseTopics, type KnowledgeFilter } from '../lib/knowledge-items';
import { renderMarkdown } from '../lib/markdown';
const props = withDefaults(defineProps<{ filter?: KnowledgeFilter; topic?: string }>(), { filter:'all', topic:'' });
const emit = defineEmits<{ metadata: [items: KnowledgeItem[]] }>();
const items=ref<KnowledgeItem[]>([]), matches=ref<KnowledgeItem[]>([]), selected=ref<KnowledgeItem|null>(null), query=ref(''), kindFilter=ref('');
const busy=ref(false),loading=ref(true),searching=ref(false),reading=ref(false),error=ref(''),notice=ref(''),editing=ref(false),topicText=ref(''),aiEnabled=ref(false),changingPolicy=ref(false),confirmDelete=ref(false);
const batch=ref<KnowledgeCollectResult|null>(null),addMenu=ref<HTMLDetailsElement|null>(null),classifying=ref(new Set<string>()),leaveAction=ref<null|(()=>void)>(null);
const draft=ref<KnowledgeItemInput>({title:'',kind:'note',body:'',notes:''});
let disposed=false, request=0, detailRequest=0, refreshRequest=0, searchTimer: ReturnType<typeof setTimeout>|undefined;
const heading=computed(()=>props.filter==='topic'?props.topic:({all:'全部知识',recent:'最近保存',pending:'待处理',favorites:'收藏',topic:'主题'})[props.filter]);
const displayed=computed(()=>filterKnowledgeItems(query.value.trim()?matches.value:items.value,props.filter,props.topic,kindFilter.value));
watch(selected,item=>{topicText.value=item?.topics.join('，')||'';});
watch(()=>[props.filter,props.topic],()=>{selected.value=null;detailRequest++;reading.value=false;});
watch(query,()=>{request++;clearTimeout(searchTimer);searching.value=!!query.value.trim();searchTimer=setTimeout(()=>void search(),180);});
async function search(){const current=++request;try{const rows=await ipc.knowledgeItemList(query.value);if(!disposed&&current===request)matches.value=rows;}catch(e){if(!disposed&&current===request)error.value=String(e);}finally{if(!disposed&&current===request)searching.value=false;}}
function excerpt(item:KnowledgeItem){return (item.notes||item.body).replace(/[#*`>\n]/g,' ').slice(0,110)||(item.hasAsset?'原件已保存，可补充笔记':'暂无正文，可继续编辑');}
function date(value:string){return new Date(value).toLocaleDateString('zh-CN');}
function guard(action:()=>void){if(busy.value)return;if(editing.value){leaveAction.value=action;}else{action();}}
defineExpose({beforeLeave:guard});
function confirmLeave(){const action=leaveAction.value;leaveAction.value=null;editing.value=false;action?.();}
function closeEditor(){guard(()=>{editing.value=false;});}
function createItem(kind:string){if(addMenu.value)addMenu.value.open=false;guard(()=>{draft.value={title:'',kind,body:'',notes:''};editing.value=true;error.value='';});}
async function selectItem(id:string){guard(()=>void readItem(id));}
async function readItem(id:string){const current=++detailRequest;reading.value=true;editing.value=false;error.value='';try{const item=await ipc.knowledgeItemGet(id);if(!disposed&&current===detailRequest)selected.value=item;}catch(e){if(!disposed&&current===detailRequest)error.value=String(e);}finally{if(!disposed&&current===detailRequest)reading.value=false;}}
function editItem(){if(!selected.value)return;draft.value={title:selected.value.title,kind:selected.value.kind,body:selected.value.body,notes:selected.value.notes,documentId:selected.value.id,expectedVersionId:selected.value.versionId};editing.value=true;}
async function refresh(){const current=++refreshRequest;loading.value=true;try{const rows=await ipc.knowledgeItemList();if(disposed||current!==refreshRequest)return;items.value=rows;emit('metadata',rows);if(selected.value&&!editing.value&&!rows.some(i=>i.id===selected.value!.id))selected.value=null;if(query.value.trim())await search();}catch(e){if(!disposed)error.value=String(e);}finally{if(!disposed)loading.value=false;}}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action();}catch(e){error.value=String(e);}finally{busy.value=false;}}
async function save(){await run(async()=>{const saved=await ipc.knowledgeItemSave(draft.value);selected.value=saved;editing.value=false;notice.value='已保存，本地检索已更新。';await refresh();void autoClassify([saved]);});}
async function collect(folder:boolean){if(addMenu.value)addMenu.value.open=false;guard(()=>void run(async()=>{const result=await ipc.knowledgeItemsPick(folder);if(!result)return;batch.value=result;notice.value=`已保存 ${result.items.length} 条，${result.failures.length} 条未保存，${result.skipped.length} 项跳过。解析未完成的原件也已保留。`;await refresh();if(result.items[0])await readItem(result.items[0].id);void autoClassify(result.items);}));}
async function retry(){if(!selected.value)return;const id=selected.value.id;await run(async()=>{const item=await ipc.knowledgeItemRetry(id);if(selected.value?.id===id)selected.value=item;await refresh();});}
async function setTopics(){if(!selected.value)return;const item=selected.value;await run(async()=>{await ipc.knowledgeItemOrganize(item.id,item.versionId,parseTopics(topicText.value));await readItem(item.id);await refresh();});}
async function acceptTopic(topic:string){topicText.value=[...(selected.value?.topics||[]),topic].join('，');await setTopics();}
async function dismissSuggestions(){if(!selected.value)return;topicText.value=selected.value.topics.join('，');await setTopics();}
async function favorite(){if(!selected.value)return;const item=selected.value;await run(async()=>{await ipc.knowledgeItemOrganize(item.id,item.versionId,undefined,!item.favorite);await readItem(item.id);await refresh();});}
async function remove(){confirmDelete.value=false;if(!selected.value)return;const id=selected.value.id;await run(async()=>{await ipc.knowledgeItemDelete(id);selected.value=null;await refresh();});}
async function exportItem(original:boolean){if(!selected.value)return;await run(async()=>{const path=await ipc.knowledgeItemExport(selected.value!.id,original);if(path)notice.value=`已导出到 ${path}`;});}
async function classify(id:string){if(classifying.value.has(id))return;classifying.value=new Set([...classifying.value,id]);try{const item=await ipc.knowledgeItemClassify(id);if(!disposed&&selected.value?.id===id&&!editing.value)selected.value=item;await refresh();}catch(e){if(!disposed)error.value=String(e);}finally{const next=new Set(classifying.value);next.delete(id);classifying.value=next;}}
async function autoClassify(rows:KnowledgeItem[]){if(!aiEnabled.value)return;for(const item of rows){if(disposed||!aiEnabled.value)break;if(item.classificationStatus==='pending' && item.modelAllowed)await classify(item.id);}}
async function changePolicy(event:Event){changingPolicy.value=true;try{aiEnabled.value=await ipc.knowledgeItemAiPolicy((event.target as HTMLInputElement).checked);await refresh();if(selected.value)await readItem(selected.value.id);if(aiEnabled.value)void autoClassify(items.value);}catch(e){error.value=String(e);}finally{changingPolicy.value=false;}}
async function onContentClick(event:MouseEvent){const target=(event.target as HTMLElement).closest<HTMLButtonElement>('button.copy-btn');if(target?.dataset.copy){try{await navigator.clipboard.writeText(decodeURIComponent(target.dataset.copy));notice.value='代码已复制';}catch(e){error.value=String(e);}}}
onMounted(async()=>{await refresh();try{aiEnabled.value=await ipc.knowledgeItemAiPolicy();if(!disposed)void autoClassify(items.value);}catch(e){if(!disposed)error.value=String(e);}});
onBeforeUnmount(()=>{disposed=true;request++;detailRequest++;clearTimeout(searchTimer);});
</script>

<style scoped>
.library{height:100%;min-height:0;display:flex;flex-direction:column;color:var(--text)}.library-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:28px 28px 20px}.library h1{font-size:24px;letter-spacing:-.03em;margin:0 0 6px}.library-header p{margin:0;font-size:13px;color:var(--muted)}button,input,select,textarea,summary{font:inherit}button{cursor:pointer;border:1px solid var(--border);border-radius:7px;background:var(--panel);color:var(--text);padding:7px 11px;font-size:12px}button:disabled{opacity:.5;cursor:default}.header-actions{display:flex;gap:8px;align-items:center}.add-menu,.more-menu{position:relative}.add-menu>summary{list-style:none;cursor:pointer;border-radius:7px;background:var(--accent);color:white;padding:9px 14px;font-size:13px}.add-menu>div,.more-menu>div{display:grid;position:absolute;right:0;top:calc(100% + 8px);z-index:8;min-width:160px;padding:6px;background:var(--panel);border:1px solid var(--border);border-radius:9px;box-shadow:0 8px 28px #00000014}.add-menu button,.more-menu button{border:0;text-align:left;padding:9px;background:transparent}.add-menu button:hover,.more-menu button:hover{background:var(--hover)}.add-menu hr{border:0;border-top:1px solid var(--border);width:100%;margin:4px 0}.library-toolbar{display:flex;gap:10px;padding:0 28px 20px}.library-toolbar input{flex:1;min-width:0}.library input,.library select,.library textarea{background:var(--panel);border:1px solid var(--border);color:var(--text);padding:9px 11px;border-radius:7px;font-size:13px}.library-content{display:grid;grid-template-columns:minmax(250px,34%) minmax(0,1fr);flex:1;min-height:350px;border-top:1px solid var(--border)}.item-list{border-right:1px solid var(--border);overflow:auto;min-width:0;background:var(--bg)}.list-heading{display:flex;justify-content:space-between;padding:14px 20px;color:var(--muted);font-size:11px}.item-row{display:grid;grid-template-columns:1fr auto;gap:7px;width:100%;border:0;border-bottom:1px solid var(--border);border-radius:0;text-align:left;padding:17px 20px;background:transparent}.item-row.selected{background:color-mix(in srgb,var(--accent) 9%,var(--panel));box-shadow:inset 3px 0 var(--accent)}.item-row:hover{background:var(--hover)}.item-row strong{grid-column:1;font-size:14px;font-weight:600;line-height:1.5;overflow-wrap:anywhere}.item-type{grid-column:1;font-size:11px;color:var(--muted)}.star{grid-column:2;grid-row:2;color:var(--accent)}.item-excerpt,.item-meta,.item-topics{grid-column:1/-1;font-size:12px;line-height:1.6;overflow-wrap:anywhere}.item-excerpt{color:var(--muted);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.item-meta{font-size:11px;color:var(--muted)}.item-topics{color:var(--accent);font-size:11px}.item-reader{min-width:0;overflow:auto;background:var(--panel)}.reader-article{padding:20px clamp(20px,3vw,48px) 36px;max-width:860px;margin:auto}.reader-actions{display:flex;justify-content:space-between;align-items:center;color:var(--muted);font-size:12px;margin-bottom:26px}.reader-actions>div{display:flex;gap:6px;align-items:center}.reader-actions button{background:transparent}.more-menu summary{list-style:none;cursor:pointer;padding:5px 9px}.reader-article h2{font-size:26px;line-height:1.4;margin:0 0 12px;overflow-wrap:anywhere}.reader-state{font-size:11px;color:var(--muted);display:flex;flex-wrap:wrap;gap:16px;margin:0 0 28px}.reader-article h3{font-size:13px;margin:0 0 12px}.reader-notes,.reader-topics{margin-top:28px;padding-top:22px;border-top:1px solid var(--border)}.reader-notes{padding:18px;border-radius:8px;background:var(--bg)}.reader-topics form{display:flex;gap:8px}.reader-topics input{min-width:0;flex:1}.suggestions{display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin:15px 0;font-size:12px}.suggestions button{color:var(--accent)}.reader-source{margin-top:25px;font-size:12px;color:var(--muted)}.reader-source summary{cursor:pointer}.reader-source p{overflow-wrap:anywhere;line-height:1.7}.help{font-size:12px;color:var(--muted);line-height:1.8}.code-body{padding:20px;border-radius:8px;background:var(--bg);overflow:auto;font-size:13px;line-height:1.8}.reader-empty,.list-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;min-height:320px;padding:30px;gap:8px;color:var(--muted);font-size:13px}.reader-empty span,.list-empty p{font-size:12px;line-height:1.8;max-width:260px;margin:0}.reader-empty p{margin:0}.processing-info{border-left:3px solid var(--accent);background:var(--bg);padding:10px 15px;font-size:12px;line-height:1.8;margin-bottom:20px}.processing-info p{margin:0 0 7px}.processing-info button{margin-right:7px}.library-footer{display:grid;gap:5px;border-top:1px solid var(--border);padding:14px 24px;font-size:11px;color:var(--muted)}.library-footer label{display:flex;align-items:center;gap:7px;color:var(--text)}.library-footer span{padding-left:22px}.library-footer input{accent-color:var(--accent)}.error,.notice,.batch-results{margin:0 28px 12px;padding:10px 12px;font-size:12px;line-height:1.8;border-radius:6px;background:var(--bg)}.error{color:#a43d39}.batch-results{max-height:180px;overflow:auto;overflow-wrap:anywhere}.item-editor{padding:22px 28px;display:grid;gap:18px}.item-editor header{display:flex;justify-content:space-between}.item-editor label{display:grid;gap:8px;font-size:12px}.item-editor textarea{resize:vertical;line-height:1.8}.item-editor .code-input{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}.item-editor .primary{background:var(--accent);color:white;border-color:var(--accent)}.back-list{display:none}button:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.knowledge-prose{font-size:14px;line-height:1.9;overflow-wrap:anywhere}.knowledge-prose :deep(h1){font-size:23px}.knowledge-prose :deep(h2){font-size:20px}.knowledge-prose :deep(h3){font-size:16px;margin-top:24px}.knowledge-prose :deep(pre){overflow:auto;background:var(--bg);border-radius:7px;padding:16px;line-height:1.7}.knowledge-prose :deep(img){max-width:100%}.knowledge-prose :deep(a){color:var(--accent)}.knowledge-prose :deep(table){display:block;overflow:auto}.knowledge-prose :deep(blockquote){border-left:3px solid var(--border);padding-left:16px;color:var(--muted)}
@media(max-width:1050px){.library-content{grid-template-columns:1fr}.item-reader{display:none}.has-selection .item-list{display:none}.has-selection .item-reader{display:block}.back-list{display:inline-block}.reader-actions>span{display:none}.library-header{padding:24px 20px 16px}.library-toolbar{padding:0 20px 16px}}@media(max-width:650px){.library-header{gap:10px}.library-header p{display:none}.library-header h1{font-size:20px}.header-actions>button{display:none}.item-editor{padding:18px}.library-footer{padding:12px}.library-toolbar{gap:6px}}
</style>
